from lib import *
S = SS('j238')
steps = [
    step("被测代码:读一个文件,每 7 次调用有 1 次在读完后抛 IOException,而异常路径没有关闭 FileInputStream(正常路径关闭)。用 UnixOperatingSystemMXBean.getOpenFileDescriptorCount() 量文件描述符:单线程测 3 次,i=1..3 一次都没有走到异常路径,fd 增量 0,断言“没有泄漏”通过;单线程 300 次,失败 42 次,fd 从 6 变成 48(增量 42);16 线程并发 2000 次,失败 285 次,fd 从 6 变成 291(增量 285)。泄漏量等于走过异常路径的次数——一个只调用 3 次的测试永远发现不了它。", t=tl(S(1)), done=lidx(S(1), 'calls=3 单线程', 'calls=300 单线程'), mark=lidx(S(1), 'calls=2000 16线程'), b=bars([['3 次调用', 0, '+0'], ['300 次单线程', 42, '+42'], ['2000 次并发', 285, '+285']], 285, done=[0, 1, 2]), kv=KV([['3 次调用的测试', 'fd 增量 0,看不出泄漏'], ['2000 次并发', 'fd 增量 285 = 失败次数']], ['2000 次并发'])),
    step("但泄漏的 FileInputStream 在 GC 之后又回来了:默认 GC 下 2000 次并发,fd 增量 285(重复 3 次都是 285),而 System.gc() 之后增量 0,因为不可达的 FileInputStream 会被 Cleaner 关闭。用 -XX:+UseEpsilonGC(不回收)运行同一段代码 3 次,System.gc() 之后增量仍是 285。修复版(try-with-resources)同样 2000 次、同样 285 次失败,fd 增量 0。所以泄漏测试要先测量、再决定是否 gc,不能为了“稳定”先 System.gc() 再量——那样会把泄漏洗掉。", t=tl(S(2)), done=lidx(S(2), '默认 GC:', 'calls=2000 16线程'), mark=lidx(S(2), '-XX:+UseEpsilonGC:', 'fixed calls=2000'), b=bars([['默认 GC:gc 之前', 285, '+285'], ['默认 GC:gc 之后', 0, '+0'], ['Epsilon:gc 之后', 285, '+285'], ['修复版', 0, '+0']], 285, done=[0, 1, 2, 3]), kv=KV([['默认 GC', 'System.gc() 后增量 0(Cleaner 关掉了泄漏的流)'], ['Epsilon GC', 'System.gc() 后仍是 285'], ['修复版', '增量 0']], ['默认 GC'])),
    step("线程泄漏:每次请求新建 newFixedThreadPool(2)、提交 2 个任务、不 shutdown。线程数增量:1 次调用 +2,10 次 +20,50 次 +100,200 次 +400;每次 System.gc() 之后增量不变(工作线程是 GC root,线程池对象被引用着)。同样次数的修复版(finally 里 shutdown + awaitTermination)增量都是 0。一个“调用 1 次、阈值 5 个线程”的测试会通过,50 次就超过了。", t=tl(S(3)), done=lidx(S(3), 'leaky n=1 ', 'leaky n=10 '), mark=lidx(S(3), 'leaky n=50 ', 'leaky n=200 ', 'fixed n=200'), b=bars([['1 次调用', 2, '+2'], ['10 次', 20, '+20'], ['50 次', 100, '+100'], ['200 次', 400, '+400']], 400, done=[0, 1, 2, 3]), kv=KV([['泄漏版', '每次调用 +2 个线程,gc 后不变'], ['修复版', '任何次数增量 0']], ['泄漏版'])),
    step("修复了但没有等线程结束:每次请求建池、提交 2 个各耗时 30 ms 的任务、调 shutdown() 后立即返回(不 awaitTermination、调用方不 get)。每 50 次调用后立即量到的线程增量是 100、200、300、400,最后一次调用后立即是 400;再等约 25–30 ms(3 次运行)增量归零。所以这里不是泄漏而是“还没结束”:测试需要在断言前等到线程数回到基线(设上限),否则会误报,而泄漏版不管等多久都不会归零。", t=tl(S(4)), done=lidx(S(4), '每 50 次调用后立即测到的线程增量'), mark=lidx(S(4), '再等到增量归零'), kv=KV([['立即量', '增量 400(线程还在跑 30 ms 的任务)'], ['等 25–30 ms', '增量 0'], ['泄漏版', '等多久都不归零']], ['立即量'])),
    step("连接池泄漏:容量 10 的 Semaphore 池,异常路径没 release。16 线程并发 200 次调用:成功 64、失败 136(其中拿不到连接而超时 126),结束时空闲连接 0/10;之后再调用 5 次(都是不会失败的 i=1),成功 0、超时 5——池已经被耗尽。修复版同样 200 次:成功 172、失败 28(其中超时 5,是 16 个线程争用 10 个连接 50 ms 的正常排队),空闲连接 10/10。检查“测试结束后空闲连接 = 容量”比检查调用是否成功更早发现问题。", t=tl(S(5)), done=lidx(S(5), '泄漏版 200 次并发调用', '之后再调用 5 次'), mark=lidx(S(5), '修复版 200 次并发调用'), b=bars([['泄漏版:结束时空闲连接', 0, '0/10'], ['修复版:结束时空闲连接', 10, '10/10']], 10, done=[0, 1]), kv=KV([['泄漏版', '空闲 0/10,之后的调用全部超时'], ['修复版', '空闲 10/10']], ['泄漏版'])),
]
A = mkartj('j238', 238, 'Java,资源泄漏,文件描述符,线程泄漏,连接池,并发测试,真实验证,动画演示',
    '实测并发下的资源泄漏测试:异常路径没关的流,3 次调用测不出,2000 次并发 fd +285;默认 GC 下 System.gc() 把泄漏洗成 0,Epsilon GC 下仍是 +285;每次请求新建线程池 200 次 +400 线程;shutdown 后不等待会瞬时多出 400 线程;容量 10 的池泄漏后之后的调用全部超时。',
    '资源泄漏通常只在并发或异常路径下出现,普通的单元测试看不到。这篇用文件描述符、线程和连接池三种资源实测:什么样的测试能发现泄漏,什么样的测试会漏掉它或误报,以及 System.gc() 如何影响结论。',
    [('+285', '16 线程并发 2000 次:异常路径没关流造成的 fd 增量(3 次调用的测试是 +0)'), ('+400', '每次请求新建线程池且不 shutdown,200 次调用后的线程数增量'), ('0/10', '连接池泄漏后并发 200 次结束时的空闲连接(修复版 10/10)')],
    [('测不到的泄漏', None), ('GC 洗掉泄漏', None), ('线程泄漏', None), ('还没结束与泄漏', None), ('连接池泄漏', None)],
    steps, [ENV_J + '。JDK 21.0.12;fd 用 com.sun.management.UnixOperatingSystemMXBean,线程数用 ThreadMXBean;被测代码与泄漏检测函数都是自写的(没有使用 JUnit 的 leak 插件或 Netty ResourceLeakDetector)', '补充观察:第一版实验里,调用方先 get() 再 shutdown(),没有等待也量不到残留线程(3 次运行都是 0),所以第 4 步改成了调用方不等待的场景;没有验证:Linux 上 /proc/self/fd 的计数方式、Socket / 文件通道 / DirectByteBuffer 的泄漏、虚拟线程、Netty 的采样式泄漏检测、真实数据库连接池(HikariCP 的 leakDetectionThreshold)'], '资源泄漏测试')
